function r(t,l){if(t.length<l)return t.map(()=>null);const a=2/(l+1),e=Array(l-1).fill(null);let s=t.slice(0,l).reduce((u,o)=>u+o.close,0)/l;e.push(s);for(let u=l;u<t.length;u++)s=t[u].close*a+s*(1-a),e.push(s);return e}function g(t,l=14){if(t.length<=l)return{values:t.map(()=>null),state:null};const a=Array(l).fill(null);let e=0,s=0;for(let n=1;n<=l;n++){const c=t[n].close-t[n-1].close;c>0?e+=c:s+=-c}e/=l,s/=l;const u=e/(s||1e-10);a.push(100-100/(1+u));for(let n=l+1;n<t.length;n++){const c=t[n].close-t[n-1].close,f=c>0?c:0,h=c<0?-c:0;e=(e*(l-1)+f)/l,s=(s*(l-1)+h)/l;const i=e/(s||1e-10);a.push(100-100/(1+i))}const o=t[t.length-1];return{values:a,state:{avgGain:e,avgLoss:s,prevClose:o.close}}}function m(t,l,a=20){let e=0;const s=t.slice(0,a).map(([n,c])=>(e+=parseFloat(c),{price:parseFloat(n),bid:e})).reverse();let u=0;const o=l.slice(0,a).map(([n,c])=>(u+=parseFloat(c),{price:parseFloat(n),ask:u}));return[...s,...o]}export{r as a,m as b,g as c};
